class Solution {
  public int maxConsistentColumns(int[][] grid, int limit) {
    int m = grid.length, n = grid[0].length;
    int[] dp = new int[n];
    int best = 1;
    for (int b = 0; b < n; b++) {
      dp[b] = 1;
      for (int a = 0; a < b; a++) {
        boolean ok = true;
        for (int i = 0; i < m && ok; i++) if (Math.abs(grid[i][b] - grid[i][a]) > limit) ok = false;
        if (ok) dp[b] = Math.max(dp[b], dp[a] + 1);
      }
      best = Math.max(best, dp[b]);
    }
    return best;
  }
}
